import os,sys,re,glob
REV=int(sys.argv[1]); ENV=sys.argv[2]; HOST=sys.argv[3]
def getfile(rel):  # rel to /app/config
    revs=sorted(int(d[1:]) for d in os.listdir('/app/config-history') if d.startswith('r'))
    for r in revs:
        if r>REV:
            p=f'/app/config-history/r{r:04d}/prev/{rel}'
            if os.path.exists(p): return open(p).read()
    return open('/app/config/'+rel).read()
def read(rel,svc,cfg,seen=0):
    txt=getfile(rel); sec=None
    for l in txt.splitlines():
        l=l.strip()
        if not l or l.startswith('#'): continue
        if l.startswith('['): sec=l[1:-1]; continue
        k,_,v=[x.strip() for x in l.partition('=')]
        if sec is None or sec==svc:
            if k=='include':
                if sec is None:
                    p=v.replace('${env}',ENV).replace('${host}',HOST)
                    read(os.path.normpath(os.path.join(os.path.dirname(rel),p)),svc,cfg)
            else: cfg[k]=v
def resolve(svc):
    cfg={}
    for l in open(f'/app/services/{svc}/service.conf'):
        l=l.strip()
        if not l or l.startswith('#'): continue
        k,_,v=[x.strip() for x in l.partition('=')]
        if k=='include':
            p=os.path.normpath(os.path.join('/app/services',svc,v))
            read(os.path.relpath(p,'/app/config'),svc,cfg)
        else: cfg[k]=v
    return cfg
for s in sorted(os.listdir('/app/services')):
    c=resolve(s)
    en=c.get('enabled','true')
    print(s,en,int(c['port_base'])+int(c['port_offset']),c['admin_port'])
